// What the drawings take: view models register.tsx fills from the mod's state atoms, and the
// callbacks it hands in. Every renderer in ./ is a pure function of (elements, view, actions);
// none of them calls the engine, so they can be drawn and tested anywhere.

import type { AgentRec, Effort, HandoffKind, JudgeKind, JudgeRun, LadderOptions, LimitItem, Pick, Settings, Skin, StatusRequest, TierTarget } from '../../types'
import type { Appearance } from './theme'
import { t } from '../i18n'
import type { Lang } from '../i18n'

export type Surface = 'terminal' | 'desktop' | 'vscode' | 'mobile'

/** Where and how big: from `e.surface`, `e.props.bodyColumns` / `maxRows`, the clock and settings. */
export type Frame = {
  surface: Surface
  /** Cells across (`bodyColumns`). */
  columns: number
  /** Rows the band may take (`maxRows`); a pane passes its `scroll.bodyRows`. */
  maxRows: number
  /** Epoch ms when drawn; countdowns are computed from it. */
  now: number
  appearance: Appearance
  /** The desktop's skin (look.ts); the terminal draws text whatever it is. */
  skin: Skin
  lang: Lang
}

/** Desktop and the editor draw SVG; the terminal and mobile draw text. */
export function isRich(frame: Frame): boolean {
  return frame.surface === 'desktop' || frame.surface === 'vscode'
}

// ---- Dashboard -------------------------------------------------------------------------------

/**
 * auto: Auto picked it · deciding: the judge is thinking · paused: Auto cannot run on this model ·
 * off: Auto is off (the level is the app's) · manual: the person picked the level.
 */
export type EffortMode = 'auto' | 'deciding' | 'paused' | 'off' | 'manual'

export type RouteView = {
  /** `target`, or `target (requested)` when the router swapped it. */
  model: string
  provider: string
  ok: boolean
  resent: boolean
  status: string
  effort?: string
  /** Prompt tokens read from cache, in percent. */
  cachePct?: number
  seconds: number
  note?: string
}

export type DashboardView = {
  effort: {
    level: Effort | null
    mode: EffortMode
    /** The judge's reason, a few words. */
    why?: string
    /** Who gave it. */
    by?: Pick['by']
    /** When the judge started (deciding): keeps the glow's phase across redraws. */
    since?: number
  }
  /** Display name of the main chat's model ("Opus 5.5"); see modelName. */
  model: string | null
  context: { percent: number; tokens: number; window: number } | null
  /** The last main reply's cache; null when unknown. */
  cache: { expiresAt: number; ttlMs: number } | null
  /** `here`: this chat differs from Settings, set by the band's flame. */
  warm: { on: boolean; pings: number; cost: number; stopped?: string; here?: boolean }
  /** The hottest plan window, shown when present. */
  limit: { kind: string; percent: number; resetsAt?: string; save: boolean } | null
  /** Every plan window for the second row, Claude's own first. Absent until read. */
  limits?: LimitItem[]
  route: RouteView | null
  /** A line from the router side ("router not answering"), shown in place of the route. */
  notice: string | null
  auto: boolean
  /** Compact turns into a lit Handoff when advice says so, or always with handoffButton 'always'. */
  handoff: 'off' | 'advised' | 'always'
  agents: { live: number; total: number }
  logOpen: boolean
  agentsOpen: boolean
  /** The manual effort row is open. */
  effortMenu: boolean
  /** Context percent at which the swamp colour starts (settings.swampAt). */
  swampAt: number
  /** Band parts switched off: 'timer' | 'reason' | 'route'. */
  hide: readonly string[]
  /** Optional chips switched on: 'context' | 'limits'. */
  extras: readonly string[]
  isWorking: boolean
  /** The active operating mode's name; absent when none is on. */
  mode?: string
}

export type BandActions = {
  toggleAuto: () => void
  toggleWarm: () => void
  compact: () => void
  clear: () => void
  handoff: () => void
  toggleLog: () => void
  toggleAgents: () => void
  openSettings: () => void
  /** Opens or closes the manual effort row. */
  toggleEffortMenu: () => void
  /** A manual pick: Auto steps aside for it (spec §1 "Person wins"). */
  pickEffort: (effort: Effort) => void
  /** Hides the band (desktop: its × is drawn inside the band). */
  hide?: () => void
}

// ---- Alerts and cards ------------------------------------------------------------------------

export type ResultStage = 'handingOff' | 'handoffReady' | 'handoffDone' | 'compacting' | 'compacted' | 'failed'

export type AlertView =
  /** The cache expired on a big chat: the next prompt re-reads it all. */
  | { kind: 'cold'; tokens: number; idleMinutes: number }
  /** Keep-warm held the cache while the person was away. */
  | { kind: 'kept'; pings: number; tokens: number; minutesLeft: number }
  /** Context is heavy. */
  | { kind: 'swamp'; percent: number; tokens: number }
  /** A plan window at or above 80%. */
  | { kind: 'hot'; limitKind: string; percent: number; resetsAt?: string; save: boolean }
  /** The judge failed and Auto fell back. */
  | { kind: 'judgeDown'; judge: JudgeKind; reason: string; network?: boolean }
  | { kind: 'result'; stage: ResultStage; handoffKind?: HandoffKind; detail?: string }
  /** Compact with an optional note of what to keep. */
  | { kind: 'compactNote'; draft: string }
  /** The band's Clear asks before the conversation is started over. */
  | { kind: 'clear' }
  /** Quick or full handoff, and what happens after. */
  | { kind: 'handoffChoice'; handoffKind: HandoffKind; after: Settings['handoffAfter'] }

export type AlertActions = {
  compact: (note?: string) => void
  /** Runs the conversation's clear, from the Clear confirm card. */
  clear: () => void
  /** Opens the handoff choice bar. */
  handoff: () => void
  dismiss: () => void
  toggleSave: () => void
  openSettings: () => void
  /** Each change of the compact note's field. */
  noteInput: (text: string) => void
  setHandoffKind: (kind: HandoffKind) => void
  setHandoffAfter: (after: Settings['handoffAfter']) => void
  go: () => void
  /** Copies a handoff's text again (result card, after: copy). */
  copy: () => void
  /** Opens a new session in this folder with the written handoff (Confirm first's card). */
  openNew: () => void
}

// ---- Settings and setup ----------------------------------------------------------------------

export type JevState = {
  /** Where the key comes from; null when there is none. */
  source: 'env' | 'file' | 'pasted' | 'zen' | null
  test: { state: 'idle' | 'testing' | 'ok' | 'fail'; message?: string }
}

export type SettingsView = {
  settings: Settings
  jev: JevState
  /** What each rung can run (the ticked models); null until the router has answered. */
  ladder?: LadderOptions | null
}

export type SettingsActions = {
  /** Applies and saves each change immediately. */
  patch: (change: Partial<Settings>) => void
  /** Turns a mode on by id, or every mode off with ''. */
  setMode?: (id: string) => void
  /** The Jev key typed into the field (Enter). */
  jevKey: (key: string) => void
  testJev: () => void
  openAllSettings: () => void
  close: () => void
}

export type SetupStep = 1 | 2 | 3 | 4

export type SetupView = {
  step: SetupStep
  draft: Settings
  jev: JevState
}

export type SetupActions = {
  patch: (change: Partial<Settings>) => void
  jevKey: (key: string) => void
  testJev: () => void
  openAllSettings: () => void
  back: () => void
  next: () => void
  /** Saves the draft with setupDone and closes. */
  finish: () => void
  /** Closes with the defaults, setupDone. */
  skip: () => void
}

// ---- Panes -----------------------------------------------------------------------------------

export type AgentsView = {
  agents: readonly AgentRec[]
  now: number
  showDone: boolean
}

export type AgentsActions = {
  toggleDone: () => void
}

export type LogView = {
  rows: readonly StatusRequest[]
  mineOnly: boolean
  /** This session's verdicts, listed among its requests. */
  judges?: readonly JudgeRun[]
}

export type LogActions = {
  toggleScope: () => void
}

// ---- Helpers register.tsx and the drawings share ----------------------------------------------

export const EFFORTS: readonly Effort[] = ['low', 'medium', 'high', 'xhigh', 'max']

export function effortIndex(effort: Effort | null | undefined): number {
  return effort ? EFFORTS.indexOf(effort) : -1
}

export function effortName(effort: Effort, lang: Lang): string {
  return t(lang, 'band.' + effort)
}

/** Route records can contain unknown effort ids; translate only the known display values. */
export function effortLabel(value: string, lang: Lang): string {
  return EFFORTS.includes(value as Effort) ? effortName(value as Effort, lang).toLowerCase() : value
}

/** "claude-opus-5-5[1m]" → "Opus 5.5"; ids it does not know pass through, trimmed. */
export function modelName(id: string): string {
  const bare = id.replace(/\[.*?\]/g, '').replace(/^claude-/, '')
  const m = /^(opus|sonnet|haiku|fable|mythos)-(\d+)(?:-(\d{1,2}))?/.exec(bare)
  if (m) return m[1]!.charAt(0).toUpperCase() + m[1]!.slice(1) + ' ' + m[2] + (m[3] ? '.' + m[3] : '')
  // A bare alias ("sonnet") reads as its family's name.
  if (/^(opus|sonnet|haiku|fable|mythos)\b/.test(bare) && !bare.includes('-')) return bare.charAt(0).toUpperCase() + bare.slice(1)
  return bare
}

/** A TierTarget as one Select value: `agent` or `agent+model`. */
export function targetValue(target: TierTarget): string {
  return target.model ? target.agent + '+' + target.model : target.agent
}

export function targetOf(value: string): TierTarget {
  const plus = value.indexOf('+')
  return plus < 0 ? { agent: value } : { agent: value.slice(0, plus), model: value.slice(plus + 1) }
}

/**
 * A target as a person reads it: the model for Claude's own agents, else the agent; Claude's agent
 * with no model runs on the session's model and says so.
 */
export function targetLabel(target: TierTarget, lang?: Lang): string {
  if (target.model) return 'Claude ' + modelName(target.model)
  return lang && target.agent === 'general-purpose' ? t(lang, 'workers.sessionModel') : target.agent
}

type Usage = NonNullable<StatusRequest['usage']>

export function promptTokens(usage: Usage): number {
  return usage.input + usage.cached + (usage.cacheWrite ?? 0)
}

export function cachePercent(usage: Usage | undefined): number | undefined {
  if (!usage) return undefined
  const prompt = promptTokens(usage)
  return prompt > 0 ? Math.round((usage.cached / prompt) * 100) : undefined
}

// The requested name's `@effort` is the agent file's default, not what was sent; the sent effort is
// its own field.
export function modelOf(record: StatusRequest): string {
  const at = record.source.lastIndexOf('@')
  const source = at < 0 ? record.source : record.source.slice(0, at)
  // A dated id of the same model (claude-haiku-5-5-20260815 for claude-haiku-5-5) says nothing new.
  return source.startsWith(record.target) || record.target.startsWith(source) ? record.target : record.target + ' (' + source + ')'
}

export function routeOf(record: StatusRequest): RouteView {
  const route: RouteView = {
    model: modelOf(record),
    provider: record.provider,
    ok: record.ok,
    resent: record.resent === true,
    status: String(record.status),
    seconds: record.ms / 1000,
  }
  const cache = cachePercent(record.usage)
  if (record.effort) route.effort = record.effort
  if (cache !== undefined) route.cachePct = cache
  if (record.note) route.note = record.note
  return route
}

/** 1234 → "1.2k", 1_200_000 → "1.2M". */
export function compactNumber(n: number): string {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + 'M'
  if (n >= 10_000) return Math.round(n / 1000) + 'k'
  if (n >= 1000) return (n / 1000).toFixed(1) + 'k'
  return String(Math.round(n))
}

/** A countdown as the band shows it: "58m" above two minutes, "1:45" below, "cold" at zero. */
export function countdown(ms: number, lang: Lang): string {
  if (ms <= 0) return t(lang, 'band.cold')
  const s = Math.ceil(ms / 1000)
  if (s >= 120) return t(lang, 'units.minutes', { n: Math.ceil(s / 60) })
  return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0')
}

/**
 * The cache countdown as the band and the footer show it: whole minutes rounded up ("42m" … "1m"),
 * "cold" at zero. It changes once a minute, so the band redraws at most once a minute for it.
 */
export function minutesLeft(ms: number, lang: Lang): string {
  if (ms <= 0) return t(lang, 'band.cold')
  return t(lang, 'units.minutes', { n: Math.ceil(ms / 60_000) })
}

/** When minutesLeft next changes for a cache expiring at `expiresAt` (epoch ms); null once cold. */
export function nextMinuteChange(expiresAt: number, now: number): number | null {
  const left = expiresAt - now
  if (left <= 0) return null
  return expiresAt - (Math.ceil(left / 60_000) - 1) * 60_000
}

/** A duration the Agents pane shows: "12s", "4m 05s", "1h 02m". */
export function elapsed(ms: number, lang: Lang): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return t(lang, 'units.seconds', { n: s })
  const m = Math.floor(s / 60)
  if (m < 60) return t(lang, 'units.minSec', { m, s: String(s % 60).padStart(2, '0') })
  return t(lang, 'units.hourMin', { h: Math.floor(m / 60), m: String(m % 60).padStart(2, '0') })
}

/** Seconds with one decimal, as routes and log entries show them: "1.2s". */
export function seconds(value: number, lang: Lang): string {
  return t(lang, 'units.seconds', { n: value.toFixed(1) })
}

export function clockTime(at: string | number): string {
  const date = new Date(at)
  return [date.getHours(), date.getMinutes(), date.getSeconds()].map(n => String(n).padStart(2, '0')).join(':')
}

/** "resets 14:20" or "resets in 3h" from an ISO time. */
export function resetsLabel(resetsAt: string | undefined, now: number, lang: Lang): string | undefined {
  if (!resetsAt) return undefined
  const at = Date.parse(resetsAt)
  if (!Number.isFinite(at)) return undefined
  const left = at - now
  if (left <= 0) return t(lang, 'band.resetting')
  if (left < 3_600_000) return t(lang, 'band.resetsIn', { time: t(lang, 'units.minutes', { n: Math.max(1, Math.round(left / 60_000)) }) })
  if (left < 86_400_000) {
    const d = new Date(at)
    return t(lang, 'band.resetsAt', { time: String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0') })
  }
  return t(lang, 'band.resetsIn', { time: t(lang, 'units.days', { n: Math.round(left / 86_400_000) }) })
}

/** "five_hour" → "5-hour", "seven_day" → "Weekly". */
export function limitName(kind: string, lang: Lang): string {
  if (kind === 'five_hour') return t(lang, 'band.fiveHour')
  if (kind === 'seven_day') return t(lang, 'band.weekly')
  return kind.replace(/_/g, ' ')
}

// ---- Limits row ----------------------------------------------------------------------------------

/** A plan window's short name as the limits row shows it: the window, or the model's own name. */
export function limitItemName(item: Pick<LimitItem, 'kind' | 'label' | 'windowMinutes'>, lang: Lang): string {
  if (item.kind === 'five_hour' || item.kind === 'seven_day') return limitName(item.kind, lang)
  if (item.kind === 'scoped') return item.label || item.kind
  const minutes = item.windowMinutes
  if (minutes === 300) return limitName('five_hour', lang)
  if (minutes === 10080) return limitName('seven_day', lang)
  if (typeof minutes === 'number' && minutes > 0) {
    if (minutes % 1440 === 0) return t(lang, 'units.days', { n: minutes / 1440 })
    if (minutes % 60 === 0) return t(lang, 'units.hours', { n: minutes / 60 })
    return t(lang, 'units.minutes', { n: minutes })
  }
  return item.label || item.kind.replace(/_/g, ' ')
}

/** One limits group as the row heads it: a provider's own, or one of its accounts ("GPT", "GPT 1", …). */
export type LimitGroup = { key: string; provider: string; type?: string; title?: string; account: number; items: LimitItem[] }

/**
 * The groups the row draws, one per provider account, Claude's plan first (the row keeps it to the
 * last when narrow) and otherwise the router's answer order. Each window's item is unchanged.
 */
export function limitGroups(items: readonly LimitItem[]): LimitGroup[] {
  const groups: LimitGroup[] = []
  const index = new Map<string, LimitGroup>()
  for (const item of items) {
    const key = item.provider + '#' + item.account
    let group = index.get(key)
    if (!group) {
      group = { key, provider: item.provider, ...(item.type ? { type: item.type } : {}), ...(item.title ? { title: item.title } : {}), account: item.account, items: [] }
      index.set(key, group)
      groups.push(group)
    }
    group.items.push(item)
  }
  // Claude's own plan comes first however the router ordered it; a stable sort keeps the rest.
  const rank = (g: LimitGroup) => (g.type === 'anthropic' || g.provider === 'claude' ? 0 : 1)
  return groups.sort((a, b) => rank(a) - rank(b))
}

/** The head's name when the item carries none: from its kind, else its config name. */
function groupTitle(group: Pick<LimitGroup, 'provider' | 'type' | 'title'>): string {
  if (group.title) return group.title
  if (group.type === 'anthropic' || group.provider === 'claude') return 'Claude'
  if (group.type === 'chatgpt' || group.provider === 'chatgpt') return 'GPT'
  if (group.type === 'google') return 'Gemini'
  return group.provider
}

/** A group's head: "Claude", "GPT", "Gemini", or its config name; "GPT 1"/"GPT 2" when numbered. */
export function limitGroupName(group: Pick<LimitGroup, 'provider' | 'type' | 'title' | 'account'>, numbered: boolean): string {
  const title = groupTitle(group)
  return numbered ? title + ' ' + (group.account + 1) : title
}

/**
 * The groups that fit `budget`, narrowing in this order: the scoped windows (Fable, 3P, …) go
 * first, one group's at a time from the last group back, so Claude's own Fable is the last of them
 * to go (all of them going at once hid Fable for Gemini's two 3P windows, 2026-10-15); then a later
 * provider's secondary accounts (the last one first), then a later provider's whole group —
 * Claude's own group (the first) stays to the last. Null when even that does not fit (no row).
 * `width` measures a set of groups the way the row draws it.
 */
export function narrowLimitGroups(groups: readonly LimitGroup[], budget: number, width: (gs: readonly LimitGroup[]) => number): LimitGroup[] | null {
  let out = [...groups]
  for (let i = out.length - 1; i >= 0 && width(out) > budget; i--) {
    if (!out[i]!.items.some(item => item.kind === 'scoped')) continue
    out = out.map((g, j) => j === i ? { ...g, items: g.items.filter(item => item.kind !== 'scoped') } : g).filter(g => g.items.length > 0)
  }
  while (width(out) > budget && out.some(g => g.account > 0)) {
    const at = out.map(g => g.account > 0).lastIndexOf(true)
    out = out.filter((_, i) => i !== at)
  }
  while (width(out) > budget && out.length > 1) out = out.slice(0, -1)
  if (!out.length || width(out) > budget) return null
  return out
}

/** A window's hover tip: "Claude 주간 88% · 4시간 뒤 초기화". */
export function limitItemTip(item: LimitItem, group: string, lang: Lang, now: number): string {
  const reset = resetsLabel(item.resetsAt, now, lang)
  return t(lang, 'band.limitsTip', { provider: group, window: limitItemName(item, lang), value: Math.round(item.percent) + '%', reset: reset ? ' · ' + reset : '' })
}

files.types/index.d.ts:
// The mod's shared shapes. The design and the reasons are in docs/specs/2026-10-10-ripple-mod.md.

// Engine contracts must be self-contained; i18n re-exports this language type.
export type Lang = 'ko' | 'en' | 'zh' | 'ja' | 'es' | 'pt'

export type StatusLine = string | null

export type StatusRequest = {
  at: string
  source: string
  target: string
  provider: string
  status: number | string
  ok: boolean
  ms: number
  effort?: string
  usage?: { input: number; cached: number; cacheWrite?: number; output: number }
  note?: string
  /** Not ok, but the client sent it again on its own: not a failure. */
  resent?: boolean
  session?: string
  /** Sent by the session this mod runs in. */
  mine?: boolean
}

export type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'

/** The desktop's skins: the deep (dark water, the first look) and flat (the app's own surfaces). */
export type Skin = 'deep' | 'flat'

/** API usage may omit counts; the engine's ModelUsage does not expose cache TTL evidence. */
export type Usage = {
  input_tokens?: number
  output_tokens?: number
  cache_read_input_tokens?: number
  cache_creation_input_tokens?: number
  cache_creation?: {
    ephemeral_1h_input_tokens?: number
    ephemeral_5m_input_tokens?: number
  }
}

/** The bounded excerpts shared by the effort judges; attachments carry counts, not contents. */
export type JudgeInput = {
  messages: readonly { role: 'user' | 'assistant'; text: string }[]
  next: string
  attachments?: readonly { type: string }[]
  current?: { model: string; effort: Effort } | null
  contextPercent?: number
  midTurn?: boolean
}

/** Who judges: Haiku on the person's Claude login, TypeSafe's Jev, or a model through the router. */
export type JudgeKind = 'haiku' | 'jev' | 'model'
/**
 * One verdict as the log pane lists it beside the router's requests: a Jev call never reaches the
 * router, so without this nothing showed who judged, how long it took or that it fell back.
 */
export type JudgeRun = {
  at: number
  /** The effort of a prompt, or the worker for a spawn. */
  for: 'prompt' | 'worker'
  /** The judge the settings ask for, and the one that answered (Haiku when it fell back). */
  asked: JudgeKind
  by: JudgeKind
  ms: number
  effort?: Effort
  sure?: number
  /** Why the asked judge gave no verdict. */
  error?: string
}

/** Domain is the kind of work; level is its required capability, independently. */
export type Domain = 'design' | 'frontend' | 'backend' | 'infra' | 'data' | 'test' | 'docs' | 'research' | 'general'
export type Level = 'light' | 'standard' | 'deep'
/** Whether a task decides what to build (plan) or carries out what was decided (do). */
export type Kind = 'plan' | 'do'
/**
 * The worker ladder's rungs (docs/specs/2026-10-11-worker-ladder.md): the judge's level picks
 * light, standard or hard regardless of kind; only an explicit max tier selects plan.
 */
export type Rung = 'light' | 'standard' | 'hard' | 'plan'
/** One rung: what runs there and how hard it thinks. */
export type Step = { target: TierTarget; effort: Effort }
/** Historical stats include design counts from before the two-axis migration. */
export type Tier = Level | 'design'
/** How a pin stored before 2026-10-11 moved its efforts; read only to migrate it (`ladderFromPin`). */
export type Calibration = { effortOffset?: -2 | -1 | 0 | 1 | 2; floor?: Effort; ceiling?: Effort }
/**
 * The four workers' rungs, each model + effort. Loading (`normalizeSettings`) reads pins from
 * before 2026-10-11 and Auto (experimental, removed 2026-10-12) into it, and drops field rules.
 */
export type Rungs = Partial<Record<Rung, Step[]>>
export type Rule = { mode: 'ladder'; rungs: Rungs }
/** How a provider is paid for: what the Workers card tags each model with, and what presets read. */
export type Billing = 'free' | 'payg' | 'subscription'
/** A model a rung can run, as GET /api/mod-options describes it. */
export type LadderChoice = {
  target: TierTarget
  model: string
  provider: string
  billing: Billing
  /** The model's own effort ladder, in order; empty when unknown. */
  efforts: Effort[]
  /** Its cheapest measured AA cost per task, when measured. */
  cost?: number
}
/** The fill rule's wishes, by name; only `claudeGpt` is used now (the router fills empty rungs with it). */
export type PresetId = 'claude' | 'claudeGpt' | 'gpt' | 'cheap'
/** The fill as computed from the ticked models: the rungs, and the ones it had to fill otherwise. */
export type Preset = { rungs: Record<Rung, Step>; substituted: Rung[] }
export type ProviderAvailability = { usable: boolean; reason?: string; exhaustedUntil?: number }
export type LadderOptions = { until: number; choices: LadderChoice[]; providers?: Record<string, ProviderAvailability> }
export type RouterModel = { value: string; label: string; provider: string; name?: string }
export type WorkerCandidate = { target: TierTarget; model: string; provider: string }
/** A model's AA measurements (GET /api/mod-options `scores`): the fill's cost order reads them. */
export type ModelScore = { model: string; provider: string; variants: { effort: Effort | null; intelligence: number | null; costPerTask: number | null }[] }

/** An agent to spawn: a dispatchable `subagentType`, and a model only for Claude's own agents. */
export type TierTarget = { agent: string; model?: string }

/**
 * An operating mode the user made (docs/specs/2026-10-12-worker-tiers.md "Operating modes").
 * Each rung is an ordered worker list, independent of the base ladder, sharing its ticked models.
 * `until` is an epoch-ms time, the named provider's next known quota reset ('chatgpt' or another
 * ChatGPT provider, or 'anthropic' for Claude), or no automatic end.
 */
export type Mode = {
  id: string
  name: string
  rungs: Rungs
  delegation: 'normal' | 'eager'
  until: 'none' | number | { reset: string }
}

export type Settings = {
  effortAuto: boolean
  judge: JudgeKind
  /** The router model id the `model` judge asks. */
  judgeModel: string
  bias: -2 | -1 | 0 | 1 | 2
  floor: Effort
  ceiling: Effort
  /** off: never; auto: spawns of ripple:auto; all: also general-purpose spawns with no model. */
  agentAuto: 'off' | 'auto' | 'all'
  jevSource: 'typesafe' | 'zen'
  /** Only the general ladder: the four workers replaced the per-field rules (2026-10-12). */
  rules: { general: Rule }
  /**
   * The models the user ticked (docs/specs/2026-10-12-worker-tiers.md): worker agent names and
   * `general-purpose:<model>` for Claude's own. Empty means every model. Rungs run, and the fill
   * picks, only among these.
   */
  allow: string[]
  /**
   * The allow-list keys of every worker that existed when `allow` was last written (what
   * `candidateKey` returns). A key absent from this non-empty list counts as ticked on; empty means
   * either every worker is ticked (`allow` empty) or all writers predate the field (#56).
   */
  allowKnown: string[]
  /** The user's operating modes; none is built in. */
  modes: Mode[]
  /** The mode that is on, by id; absent when none is. */
  activeMode?: string
  /**
   * When the active mode was turned on (epoch ms): a mode that runs until the quota resets ends at
   * the first reset after this.
   */
  activeSince?: number
  providers: Record<string, boolean>
  /**
   * What ran when a pinned tier's agent was unavailable, before the ladder (2026-10-11). Kept so a
   * stored choice survives; the ladder moves one rung up instead.
   */
  fallback: TierTarget
  keepWarm: boolean
  keepWarmHours: 1 | 2 | 4 | 8
  keepWarmMinTokens: number
  compactWith: 'haiku' | 'session'
  handoffSkill: string
  handoffAfter: 'continue' | 'confirm' | 'copy'
  handoffButton: 'advised' | 'always'
  /** Context percent at which the context reads heavy (and the swamp band shows, when on). */
  swampAt: number
  /** The heavy-context band; off unless switched on. */
  swampAlert: boolean
  layout: 'dashboard' | 'minimal'
  appearance: 'auto' | 'dark' | 'light'
  /** How the desktop draws the band and the cards: the deep or flat (ui/look.ts). */
  skin: Skin
  language: 'auto' | Lang
  /** Band parts switched off: 'timer' | 'reason' | 'route'. */
  hide: string[]
  /** Band chips switched on, off by default: 'context' | 'limits'. */
  extras: string[]
  setupDone: boolean
}

/** The admin API always returns a complete normalized settings object. */
export type ModSettingsSnapshot = {
  settings: Settings
  revision: number
  stored: boolean
  /** The stored settings still held field overrides or Auto, which the four workers replaced; true until the next save. */
  legacy?: boolean
}
/** Arrays and rule mode changes are atomic; other edits are rebased by field path. */
export type SettingsChange = { path: string[]; value?: unknown; remove?: boolean }
export type SettingsSync = { schemaVersion?: number; revision: number | null; pending: SettingsChange[]; migrationChecked: boolean; migration: Settings | null }

/** A judge's answer for the main chat's next prompt. */
export type Verdict = { effort: Effort; sure?: number; why: string }

/** The effort the main chat runs at now, and who set it. */
export type Pick = Verdict & { by: JudgeKind | 'manual' | 'followup'; at: number }

/** A judge's answer for a delegated task; a judge that names no kind means do. */
export type WorkerVerdict = {
  domain: Domain; level: Level; kind?: Kind; effort: Effort
  /** Confidence in the level, the one that moves a task up the ladder. */
  sure?: number
  /** Jev's confidence in each answer, kept in the pick log so a rubric change can be compared. */
  odds?: { domain?: number; level?: number; kind?: number; effort?: number }
  why: string
}

/** What a spawn of ripple:auto (or a taken-over spawn) was turned into. */
export type WorkerPick = WorkerVerdict & {
  /** The ladder rung that ran it (absent for explicit choices). */
  rung?: Rung
  /** One-based position in the selected rung; skipped entries explain ordered fallback. */
  position?: number
  skipped?: { rung: Rung; position: number; model: string; reason: string }[]
  target: TierTarget
  /** Who named the tier: the judge, the main chat's tier marker (`session`), a model marker, or the default. */
  by: JudgeKind | 'session' | 'marker' | 'default'
  ms: number
  /** Set when the tier's own agent could not run and the fallback did. */
  fallbackReason?: string
  /** Joins the pick's lines in the pick log: the pick, the judge's shadow verdict, the outcome. */
  id?: string
}

export type AgentState = 'running' | 'waiting' | 'done' | 'failed'

export type AgentRec = {
  id: string
  description: string
  /** The agent type that ran. */
  type: string
  model?: string
  pick?: WorkerPick
  state: AgentState
  /** The tool it is in now, in a few words. */
  now?: string
  toolSince?: number
  startedAt: number
  endedAt?: number
  /** Weighted tokens (spec §5 stats weights). */
  cost: number
}

/** The main chat's prompt cache as far as its responses show it. */
export type CacheMemo = {
  ttlMs: number
  lastReplyAt: number
  expiresAt: number
}

/** Keep-warm bookkeeping for this chat. */
export type WarmState = {
  pings: number
  /** Weighted tokens the pings cost. */
  cost: number
  /** Set when keep-warm stopped by itself, with why. */
  stopped?: string
  lastPingAt?: number
}

/** The hottest plan window at or above the alert line. */
export type Hot = { kind: string; percent: number; resetsAt?: string }

/**
 * One plan window for the band's second row, the limits row: every window of every provider whose
 * quota the router can read (Claude's plan windows and per-model weeklies, each ChatGPT account's
 * windows, each Antigravity account's Gemini and third-party windows). The row reads them all from
 * `GET /api/limits` (falling back to the older status routes on a router that predates it).
 * `provider` is the provider's config name (the grouping key; 'claude' on the fallback path);
 * `type` is its kind ('anthropic', 'chatgpt', 'google', …), which picks the group head's colour;
 * `title` is the head's name ("Claude", "GPT", "Gemini"); `account` numbers the provider's eligible
 * accounts from 0 (the row reads "GPT" alone, or "GPT 1", "GPT 2", … when a provider has several);
 * `kind` is 'five_hour', 'seven_day', 'scoped' (a per-model/third-party window, its name in `label`)
 * or 'window' (a window of another length, its minutes in `windowMinutes`).
 */
export type LimitItem = {
  provider: string
  /** The provider's kind, for the head's colour. Absent on an older item, the name stands in. */
  type?: string
  /** The head's name; absent, derived from the provider's type or name. */
  title?: string
  account: number
  kind: 'five_hour' | 'seven_day' | 'scoped' | 'window'
  label: string
  windowMinutes?: number
  percent: number
  resetsAt?: string
}

export type Stats = {
  prompts: number
  requests: number
  input: number
  write: number
  read: number
  out: number
  byEffort: Partial<Record<Effort, { prompts: number; cost: number }>>
  judge: { haiku: number; jev: number; model: number; ms: number; tokens: number }
  workers: Partial<Record<Tier, number>>
  warm: { pings: number; cost: number }
}

export type HandoffKind = 'quick' | 'full'
/** `ready`: written, waiting on Confirm first's card; `opened`: a new session was opened with it. */
export type HandoffStage = 'writing' | 'clearing' | 'done' | 'ready' | 'opened' | 'copied' | 'failed'
export type SetupStep = 1 | 2 | 3 | 4
export type ResultStage = 'handingOff' | 'handoffReady' | 'handoffDone' | 'compacting' | 'compacted' | 'failed'
export type JevState = {
  source: 'env' | 'file' | 'pasted' | 'zen' | null
  test: { state: 'idle' | 'testing' | 'ok' | 'fail'; message?: string }
}

declare module 'claude-code' {
  interface PluginState {
    ripple: {
      line: StatusLine
      last: StatusRequest | null
      requests: StatusRequest[]
      logOpen: boolean
      onlySession: boolean
      bandHidden: boolean
      settings: Settings | null
      settingsSync: SettingsSync
      settingsBase: Settings | null
      lang: Lang
      pick: Pick | null
      deciding: boolean
      paused: boolean
      agents: AgentRec[]
      cache: CacheMemo | null
      warm: WarmState
      /** Keep-warm for this chat alone, set by the band's flame; null follows Settings. */
      warmHere: boolean | null
      context: { percent: number; tokens: number; window: number } | null
      hot: Hot | null
      hotHidden: number | null
      /** The window the hot card was put off for: the put-off lasts until that window moves on. */
      hotHiddenFor: Hot | null
      saveUntil: number | null
      swampHidden: number | null
      coldHidden: boolean
      kept: { pings: number; tokens: number } | null
      judgeDown: string | null
      advice: string | null
      handoff: { stage: HandoffStage; kind: HandoffKind; text?: string } | null
      panel: 'settings' | 'setup' | 'compact' | 'clear' | 'handoff' | null
      busy: boolean
      decidingSince: number | null
      heldPick: Pick | null
      appEffort: Effort | number | null
      modelIs: string | null
      lastRequest: { model: string; appEffort?: string | number; sentEffort?: string | number } | null
      lastSpawn: WorkerPick | null
      lastRealReplyAt: number | null
      stats: Stats
      promptCount: number
      adviceQueue: string | null
      handoffQueued: boolean
      handoffWaiting: boolean
      handoffChoiceKind: HandoffKind
      handoffChoiceAfter: 'continue' | 'confirm' | 'copy'
      result: { stage: ResultStage; detail?: string } | null
      settingsDraft: Settings | null
      setupStep: SetupStep
      compactNote: string
      effortMenuOpen: boolean
      agentsOpen: boolean
      agentsShowDone: boolean
      jev: JevState
      routerModels: RouterModel[]
      /** The router's rung choices and presets (GET /api/mod-options), for the quick settings. */
      ladderOptions: LadderOptions | null
      /** The active mode the eager note was last sent for (`modes.ts modeKey`); cleared on compaction. */
      modeNoted: string | null
      judgeDownHidden: string | null
      /** Judge failure reasons already said this session. */
      judgeSeen: string[]
      judgeRuns: JudgeRun[]
      judgeDownNetwork: boolean
      limit: Hot | null
      /** Every provider's plan windows for the limits row, from `GET /api/limits`. Null until read. */
      limits: LimitItem[] | null
      demo: 'cold' | 'swamp' | 'hot' | 'down' | 'kept' | null
    }
  }
}

